package com.aditya.fefo.infrastructure; import com.aditya.fefo.service.*; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; @Component public class ExpiryScheduler {private final ReservationService reservations;private final BatchExpiryService batches;public ExpiryScheduler(ReservationService r,BatchExpiryService b){reservations=r;batches=b;}@Scheduled(fixedDelayString="${EXPIRY_JOB_MS:30000}") public void expire(){reservations.expireHolds();batches.markExpired();}}
